insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 0, null, 'KAPITOLA 1   Cíl 1.1 KAPITOLA 2   Rozsah působnosti 2.1 a) těch majetkových účastí v dceřiných společnostech, přidružených společnostech nebo společných podnicích, o nichž se účtuje v souladu s IFRS 10 Konsolidovaná účetní závěrka, IAS 27 Samostatná účetní závěrka nebo IAS 28 Investice do přidružených podniků a společných podniků. V určitých případech však standardy IFRS 10, IAS 27 nebo IAS 28 vyžadují nebo umožňují účetní jednotce účtovat o podílech v dceřiných a přidružených podnicích a ve společných podnicích v souladu s některými nebo všemi požadavky tohoto standardu. Účetní jednotky použijí tento standard také na deriváty podílů v dceřiných a přidružených podnicích a ve společných podnicích, pokud derivát nenaplňuje definici kapitálového nástroje účetní jednotky tak, jak je vymezen v IAS 32 Finanční nástroje: vykazování; b) práv a závazků z leasingu, které se účtují podle IFRS 16 Leasingy. Platí však, že: i) pro pohledávky z finančního leasingu (tj. čisté investice u finančních leasingů) a pro pohledávky z operativního leasingu uznané pronajímatelem platí požadavky tohoto standardu týkající se vynětí a znehodnocení; ii) pro závazky z leasingu uznané nájemcem platí požadavky na vynětí podle odstavce 3.3.1 tohoto standardu a iii) pro deriváty vložené do leasingových smluv platí požadavky tohoto standardu týkající se vložených derivátů; c) práv a závazků zaměstnavatelů vůči zaměstnancům z plánů zaměstnaneckých požitků, jejichž účtování upravuje IAS 19 Zaměstnanecké požitky;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 1, null, 'd) finančních nástrojů emitovaných účetní jednotkou, které splňují definici kapitálového nástroje podle IAS 32 (včetně opcí a warrantů) nebo které musejí být klasifikovány jako kapitálové nástroje v souladu s odstavci 16A a 16B nebo odstavci 16C a 16D IAS 32. Avšak držitel takových kapitálových nástrojů musí tento standard na tyto nástroje použít, pokud nesplňují výjimku uvedenou v písmenu a); e) práv a závazků vyplývajících z pojistné smlouvy ve smyslu IFRS 17 Pojistné smlouvy nebo investiční smlouvy s prvky dobrovolné účasti v rozsahu působnosti IFRS 17. Avšak tento standard platí pro: i) deriváty vložené do pojistných smluv spadajících do rozsahu působnosti IFRS 17, pokud tyto deriváty nejsou samy smlouvami v rozsahu působnosti IFRS 17; ii) investiční složky, které jsou odděleny od smluv spadajících do rozsahu působnosti IFRS 17, jestliže IFRS 17 takové oddělení požaduje, pokud oddělená investiční složka není investiční smlouvou s prvky dobrovolné účasti v rozsahu působnosti IFRS 17; iii) práva a závazky výstavce podle pojistných smluv, které splňují definici smlouvy o finanční záruce. Pokud však výstavce smluv o finanční záruce předem výslovně stanovil, že takové smlouvy považuje za smlouvy pojistné, a použil při jejich účtování postupy, které jsou platné pro pojistné smlouvy, může si sám rozhodnout, zda použije pro takové smlouvy o finanční záruce tento standard, nebo IFRS 17 (viz odstavce B2.5–B2.6). Poskytovatel může toto rozhodnutí učinit pro každou smlouvu zvlášť, ale tuto volbu nemůže pro danou smlouvu následně změnit;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 2, null, 'iv) práva a závazky účetní jednotky, které představují finanční nástroje vyplývající ze smluv o kreditních kartách, nebo podobných smluv, které obsahují úvěrové nebo platební ujednání, jež účetní jednotka vystavuje, a které splňují definici pojistné smlouvy, ale které jsou podle odst. 7 písm. h) IFRS 17 vyloučeny z rozsahu působnosti IFRS 17. Avšak pouze tehdy, pokud je pojistné krytí smluvní podmínkou tohoto finančního nástroje, účetní jednotka oddělí tuto složku a uplatní na ni IFRS 17 (viz odst. 7 písm. h) IFRS 17); v) práva a závazky účetní jednotky, které představují finanční nástroje vyplývající z pojistných smluv, jež účetní jednotka vystavuje, a které omezují odškodnění za pojistné události na částku, která je jinak požadována k uhrazení smluvně vzniklého závazku pojistníka, jestliže si účetní jednotka zvolí pro tyto smlouvy v souladu s odstavcem 8A standardu IFRS 17 použití standardu 9 místo standardu 17; f) jakýchkoli forwardových smluv mezi nabyvatelem a prodávajícím společníkem na nákup nebo prodej nabývané společnosti, v jehož důsledku vznikne podniková kombinace zahrnutá do rozsahu působnosti IFRS 3 Podnikové kombinace s datem akvizice v budoucnosti. Trvání této forwardové smlouvy by nemělo přesáhnout přiměřenou lhůtu běžně potřebnou k získání všech požadovaných povolení a k dokončení transakce;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 3, null, 'g) úvěrových příslibů s výjimkou úvěrových příslibů uvedených v odstavci 2.3. U úvěrových příslibů, které jinak nespadají do působnosti tohoto standardu, však bude výstavce úvěrového příslibu postupovat podle požadavků na znehodnocení stanovených tímto standardem. Pro všechny úvěrové přísliby rovněž platí požadavky na vynětí podle tohoto standardu; h) finančních nástrojů, smluv a závazků vyplývajících z transakcí s úhradou vázanou na akcie, které upravuje IFRS 2 Úhrady vázané na akcie, s výjimkou smluv spadajících do působnosti odstavců 2.4–2.7 tohoto standardu, pro něž platí tento standard; i) práv na náhradu výdajů, jež účetní jednotce vzniknou v souvislosti s vypořádáním závazku, který je uznán jako rezerva v souladu s IAS 37 Rezervy, podmíněné závazky a podmíněná aktiva nebo v souvislosti s nímž účetní jednotka uznala rezervu podle IAS 37 v předchozím účetním období; j) práv a závazků spadajících do působnosti IFRS 15 Výnosy ze smluv se zákazníky, které jsou finančními nástroji, s výjimkou práv a závazků, pro něž IFRS 15 stanoví, že se účtují v souladu s tímto standardem. 2.2 2.3 a) úvěrové přísliby, které účetní jednotka označí za finanční závazky v reálné hodnotě vykázané do hospodářského výsledku (viz odstavec 4.2.2). Účetní jednotka, která v minulosti prodávala aktiva pocházející z jejích úvěrových příslibů krátce po poskytnutí úvěru, musí tento standard aplikovat na všechny své úvěrové přísliby zařazené do stejné třídy;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 4, null, 'b) úvěrové přísliby, které lze vypořádat v čisté výši hotově nebo poskytnutím či vystavením jiného finančního nástroje. Tyto úvěrové přísliby jsou deriváty. Úvěrový příslib se nepovažuje za vypořádaný v čisté výši pouze proto, že úvěr je splácen ve splátkách (například stavební hypoteční úvěr, který je splácen ve splátkách korespondujících s postupem stavebních prací); c) přísliby poskytnout úvěr s úrokem nižším, než je tržní úroková míra (viz odst. 4.2.1 písm. d). 2.4 2.5 2.6 a) když podmínky smlouvy umožňují některé ze smluvních stran vypořádat smlouvu čistou částkou v hotovosti nebo jiným finančním nástrojem nebo směnou finančních nástrojů; b) když možnost vypořádat smlouvu čistou částkou v hotovosti nebo jiným finančním nástrojem nebo směnou finančních nástrojů není výslovně určena podmínkami smlouvy, ale účetní jednotka běžně podobné smlouvy takovým způsobem vypořádává (ať už s druhou stranou, nebo formou smlouvy o vyrovnání, nebo prodejem smlouvy před její realizací nebo zánikem); c) když u podobných smluv účetní jednotka běžně postupuje tak, že převezme podkladový nástroj a během krátkého období po dodání ho prodá za účelem zisku z krátkodobé fluktuace ceny nebo marže obchodníka, a d) když nefinanční položka, která je předmětem smlouvy, je pohotově směnitelná za hotovost.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 5, null, 'Smlouva, na kterou se vztahuje písmeno b) nebo c), se neuzavírá za účelem přijetí nebo dodání nefinanční položky pro potřeby očekávané koupě, prodeje nebo užívání, a proto spadá do působnosti tohoto standardu. U dalších smluv, na které se vztahuje odstavec 2.4, se posoudí, zda byly uzavřeny a jsou nadále drženy za účelem přijetí nebo dodání nefinanční položky pro potřeby očekávané koupě, prodeje nebo užívání, a zda tedy spadají do působnosti tohoto standardu, či nikoliv. 2.7 KAPITOLA 3   Uznání a vynětí 3.1   PRVOTNÍ UZNÁNÍ 3.1.1 Spotový nákup nebo prodej finančních aktiv 3.1.2 3.2   VYNĚTÍ FINANČNÍCH AKTIV 3.2.1 3.2.2 a) odstavce 3.2.3–3.2.9 se použijí u části finančního aktiva (nebo části skupiny podobných finančních aktiv) pouze tehdy, pokud část zvažovaná k vynětí splňuje jednu z následujících tří podmínek: i) část obsahuje pouze konkrétně identifikované peněžní toky z finančního aktiva (nebo skupiny podobných finančních aktiv). Například když účetní jednotka uzavře úrokový strip, jímž druhá strana získá právo na úrokové peněžní toky, ale nikoli na jistinné toky z úvěrového nástroje, použijí se na úrokové peněžní toky odstavce 3.2.3–3.2.9;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 6, null, 'ii) část obsahuje pouze poměrný (pro-rata) podíl na peněžních tocích z finančního aktiva (nebo skupiny podobných finančních aktiv). Například pokud účetní jednotka uzavře dohodu, jíž druhá strana nabude práva na 90 % podíl ze všech peněžních toků dluhového nástroje, odstavce 3.2.3–3.2.9 se použijí na těchto 90 % peněžních toků. Pokud existuje více než jedna smluvní strana, není nutné, aby každá z nich měla poměrný podíl na peněžních tocích, stačí, když poměrný podíl má postupující účetní jednotka; iii) část obsahuje pouze poměrný (pro-rata) podíl na specificky identifikovaných peněžních tocích z finančního aktiva (nebo skupiny podobných finančních aktiv). Například pokud účetní jednotka uzavře dohodu, již druhá strana nabude práva na 90 % podíl z úrokových plateb z finančního aktiva, odstavce 3.2.3–3.2.9 se použijí u 90 % z těchto plateb. Pokud existuje více než jedna smluvní strana, není nutné, aby každá z nich měla poměrný podíl na konkrétně identifikovaných peněžních tocích, stačí, když poměrný podíl má postupující účetní jednotka;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 7, null, 'b) ve všech ostatních případech se odstavce 3.2.3–3.2.9 použijí na finanční aktivum jako celek (nebo na skupinu podobných finančních aktiv jako celek). Například pokud účetní jednotka převede i) práva na prvních nebo posledních 90 % peněžních inkas z finančního aktiva (nebo skupiny finančních aktiv) nebo ii) práva na 90 % peněžních toků ze skupiny pohledávek, ale poskytne kupujícímu záruku za jakékoli úvěrové ztráty až do výše 8 % z jistiny pohledávek, použijí se odstavce 3.2.3–3.2.9 u finančního aktiva (nebo skupiny podobných finančních aktiv) jako celku. V odstavcích 3.2.3–3.2.12 se pojem „finanční aktivum“ vztahuje buď na část finančního aktiva (nebo část skupiny podobných finančních aktiv), jak bylo popsáno v písmenu a) výše, nebo na finanční aktivum (nebo skupinu podobných finančních aktiv) jako celek. 3.2.3 a) smluvní práva na peněžní toky z finančního aktiva vyprší, nebo b) převede finanční aktivum, jak je uvedeno v odstavcích 3.2.4 a 3.2.5, a převod splňuje podmínky pro vynětí podle odstavce 3.2.6. (Spotové prodeje finančních aktiv viz odstavec 3.1.2.) 3.2.4 a) převede smluvní práva na peněžní toky z finančního aktiva, nebo b) si ponechá smluvní práva na peněžní toky z finančního aktiva, ale formou dohody, která splňuje podmínky odstavce 3.2.5, přijme smluvní závazek platit peněžní toky jednomu nebo více příjemcům.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 8, null, '3.2.5 a) účetní jednotka nemá povinnost platit částky konečným příjemcům, pokud nebude inkasovat ekvivalentní částky z původního aktiva. Krátkodobé zálohy přijaté účetní jednotkou s právem na plné vrácení vypůjčené částky, navýšené o dlužný úrok ve výši obvyklé na trhu, tuto podmínku neporušují; b) účetní jednotka na základě smlouvy o převodu nesmí původní aktivum prodat ani zastavit jinak, než jako záruku konečným příjemcům za závazek platit jim peněžní toky; c) účetní jednotka je povinna poukazovat konečným příjemcům všechny inkasované platby bez významného prodlení. Účetní jednotka navíc není oprávněna takové peněžní toky reinvestovat, kromě investic do hotovosti nebo hotovostních ekvivalentů (dle definice v IAS 7 Výkazy peněžních toků) během krátkého období vypořádání mezi datem inkasa a datem požadovaného poukázání konečným příjemcům, a úrok získaný z takových investic je předán konečným příjemcům. 3.2.6 a) pokud účetní jednotka převede v podstatě všechna rizika a užitky spojené s vlastnictvím finančního aktiva, musí vyjmout finanční aktivum a uznat zvlášť jako aktiva nebo závazky jakákoli práva a závazky vzniklé nebo ponechané při převodu; b) pokud si účetní jednotka ponechá v podstatě všechna rizika a užitky spojené s vlastnictvím finančního aktiva, musí nadále toto finanční aktivum uznávat; c) pokud účetní jednotka ani nepřevede, ani si neponechá v podstatě všechna rizika a užitky spojené s vlastnictvím finančního aktiva, musí zjistit, zda si zachovala kontrolu nad finančním aktivem. V takovém případě:'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 9, null, 'i) pokud si účetní jednotka nezachovala nad finančním aktivem kontrolu, musí ho vyjmout a uznat zvlášť jako aktiva nebo závazky jakákoli práva a závazky vzniklé nebo ponechané při převodu; ii) pokud si účetní jednotka zachovala nad finančním aktivem kontrolu, musí ho nadále uznávat v rozsahu své přetrvávající angažovanosti ve finančním aktivu (viz odstavec 3.2.16). 3.2.7 3.2.8 3.2.9 Převody, které splňují podmínky pro vynětí 3.2.10 3.2.11 3.2.12 a) účetní hodnotou těchto aktiv (oceněnou ke dni vynětí) a b) přijatou úhradou (včetně jakéhokoli nově nabytého aktiva sníženého o hodnotu jakéhokoli nově přijatého závazku) uznat do hospodářského výsledku. 3.2.13 a) účetní hodnotou těchto aktiv (oceněnou ke dni vynětí) přiřazenou vyňaté části a b) přijatou úhradou za vyňatou část (včetně jakéhokoli nově nabytého aktiva sníženého o hodnotu jakéhokoli nově přijatého závazku) uznat do hospodářského výsledku. 3.2.14 Převody, které nesplňují podmínky pro vynětí 3.2.15 Přetrvávající angažovanost v převáděných aktivech 3.2.16 a) pokud přetrvávající angažovanost účetní jednotky nabude formy ručení za převáděné aktivum, rozsah přetrvávající angažovanosti účetní jednotky určuje nižší z i) hodnoty aktiva a ii) maximální částky přijatého plnění, jejíž splacení by po účetní jednotce mohlo být požadováno („záruční částka“);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 10, null, 'b) pokud přetrvávající angažovanost účetní jednotky nabude formy vystavené nebo držené opce (nebo obou) na převáděné aktivum, rozsahem přetrvávající angažovanosti účetní jednotky je hodnota převáděného aktiva, kterou může účetní jednotka zpětně koupit. Avšak v případě vystavené prodejní opce na aktivum, které je oceněno reálnou hodnotou, je rozsah přetrvávající angažovanosti účetní jednotky limitován částkou reálné hodnoty převáděného aktiva nebo realizační cenou opce, je-li nižší (viz odstavec B3.2.13); c) pokud přetrvávající angažovanost účetní jednotky nabude formy v hotovosti vypořádané opce nebo podobné operace s převáděným aktivem, rozsah přetrvávající angažovanosti se ocení stejným způsobem jako v případě uvedeném výše v písmenu b), kdy jde o opce nevypořádané v hotovosti. 3.2.17 a) naběhlá hodnota práv a závazků, které si účetní jednotka ponechala v případě, že se převáděné aktivum oceňuje naběhlou hodnotou, nebo b) rovna reálné hodnotě práv a závazků, které si účetní jednotka ponechala při nezávislém ocenění, to v případě, že je převáděné aktivum oceňováno reálnou hodnotou. 3.2.18 3.2.19 3.2.20 a) účetní hodnotou těchto aktiv (oceněnou ke dni vynětí) přiřazenou části, která není nadále uznávána, a b) úhradou přijatou za část, která není nadále uznávána, uznat do hospodářského výsledku. 3.2.21 Veškeré převody'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 11, null, '3.2.22 3.2.23 a) pokud má přejímající ze smlouvy nebo ze zvyklosti právo prodat nebo znovu zastavit kolaterál, potom předávající musí toto aktivum reklasifikovat ve svém výkazu o finanční pozici (např. jako půjčené aktivum, poskytnuté kapitálové nástroje nebo pohledávku ze zpětné koupě) odděleně od ostatních aktiv; b) pokud přejímající prodá zastavený kolaterál, musí uznat příjmy z prodeje a závazek vyplývající z povinnosti vrátit kolaterál oceněný reálnou hodnotou; c) pokud převádějící nesplní závazek plynoucí z podmínek smlouvy a nemá nadále právo umořit kolaterál, musí kolaterál vyjmout a přejímající musí kolaterál uznat jako své aktivum prvotně oceněné reálnou hodnotou, resp. pokud již kolaterál prodal, vyjmout svůj závazek vrátit kolaterál; d) kromě případů uvedených v písmenu c) musí převádějící nadále účtovat o kolaterálu jako o svém aktivu a přejímající nesmí kolaterál uznat jako aktivum. 3.3   VYNĚTÍ FINANČNÍCH ZÁVAZKŮ 3.3.1 3.3.2 3.3.3 3.3.4 3.3.5 KAPITOLA 4   Klasifikace 4.1   KLASIFIKACE FINANČNÍCH AKTIV 4.1.1 a) obchodního modelu účetní jednotky pro řízení finančních aktiv a současně b) charakteristiky smluvních peněžních toků finančního aktiva. 4.1.2 a) finanční aktivum je drženo v rámci obchodního modelu, jehož cílem je držet finanční aktiva za účelem získání smluvních peněžních toků, a b) smluvní podmínky finančního aktiva stanoví konkrétní data peněžních toků tvořených výlučně splátkami jistiny a úroků z nesplacené částky jistiny. Odstavce B4.1.1–B4.1.26 obsahují pokyny, jak tyto podmínky uplatňovat. 4.1.2A'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 12, null, 'a) finanční aktivum je drženo v rámci obchodního modelu, jehož cíle je dosaženo jak inkasem smluvních peněžních toků, tak prodejem finančních aktiv, a b) smluvní podmínky finančního aktiva stanoví konkrétní data peněžních toků tvořených výlučně splátkami jistiny a úroků z nesplacené částky jistiny. Odstavce B4.1.1–B4.1.26 obsahují pokyny, jak tyto podmínky uplatňovat. 4.1.3 a) jistina je reálná hodnota finančního aktiva při prvotním uznání. Odstavec B4.1.7B poskytuje další vysvětlení k významu pojmu jistiny. b) úrok zohledňuje časovou hodnotu peněz, úvěrové riziko spojené s nesplacenou částkou jistiny za konkrétní časové období a další základní rizika a náklady spojené s poskytováním úvěrů, jakož i ziskovou marži. Odstavce B4.1.7A a B4.1.9A–B4.1.9E poskytují další vysvětlení k významu pojmu úroku včetně významu časové hodnoty peněz. 4.1.4 Možnost zařadit finanční aktivum do kategorie oceňované reálnou hodnotou do hospodářského výsledku 4.1.5 4.2   KLASIFIKACE FINANČNÍCH ZÁVAZKŮ 4.2.1 a) finančních závazků oceňovaných reálnou hodnotou do hospodářského výsledku. Takové závazky, včetně derivátů, které jsou závazky, se musí následně oceňovat reálnou hodnotou; b) finančních závazků, které vzniknou, pokud převod finančního aktiva nesplňuje podmínky pro vynětí nebo pokud je pro něj třeba použít metodu přetrvávající angažovanosti. Při oceňování takových finančních závazků se použijí odstavce 3.2.15 a 3.2.17; c) smluv o finanční záruce. Po prvotním uznání bude ručitel (neuplatní-li se odst. 4.2.1 písm. a) nebo b)) následně oceňovat:'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 13, null, 'i) ve výši opravné položky určené v souladu s oddílem 5.5 a ii) částkou prvotního uznání (viz odstavec 5.1.1) sníženou případně o kumulovanou částku výnosů uznanou v souladu se zásadami IFRS 15, je-li vyšší; d) příslibů poskytnout úvěr s úrokem nižším, než je tržní úroková míra. Výstavce tohoto příslibu následně ocení takový příslib (neuplatní-li se odst. 4.2.1 písm. a)): i) ve výši opravné položky určené v souladu s oddílem 5.5 a ii) částkou prvotního uznání (viz odstavec 5.1.1) sníženou případně o kumulovanou částku výnosů uznanou v souladu se zásadami IFRS 15, je-li vyšší; e) podmíněné protihodnoty zaúčtované nabyvatelem v podnikové kombinaci, na kterou se vztahuje IFRS 3. Taková podmíněná protihodnota musí být následně oceňována reálnou hodnotou se změnami uznanými do hospodářského výsledku. Možnost zařadit finanční závazek do kategorie oceňované reálnou hodnotou do hospodářského výsledku 4.2.2 a) vylučuje nebo podstatně omezuje nesoulad ocenění nebo uznání (někdy označovaný jako „účetní neshoda“), který by mohl jinak vzniknout při oceňování aktiv nebo závazků nebo uznávání příslušných zisků a ztrát na jiném základě (viz odstavce B4.1.29–B4.1.32), nebo'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 14, null, 'b) skupina finančních závazků nebo finančních aktiv a finančních závazků je řízena a její výkonnost je hodnocena na základě reálné hodnoty a v souladu se zdokumentovanou strategií řízení rizik nebo investiční strategií a informace o této skupině jsou na tomto základě interně předávány klíčovému vedení účetní jednotky (podle definice v IAS 24 Zveřejnění spřízněných stran), například představenstvu společnosti a generálnímu řediteli (viz odstavce B4.1.33–B4.1.36). 4.3   VLOŽENÉ DERIVÁTY 4.3.1 Hybridní smlouvy s hostitelskými smlouvami týkajícími se finančních aktiv 4.3.2 Jiné hybridní smlouvy 4.3.3 a) ekonomické rysy vloženého derivátu a rizika s ním spojená nesouvisejí úzce s ekonomickými rysy hostitelské smlouvy a s riziky s ní spojenými (viz odstavce B4.3.5 a B4.3.8); b) samostatný nástroj se stejnými podmínkami jako vložený derivát by vyhověl definici derivátu a c) hybridní smlouva není oceněna reálnou hodnotou se změnami reálné hodnoty uznávanými do hospodářského výsledku (tj. derivát, který je vložen ve finančním závazku oceňovaném reálnou hodnotou do hospodářského výsledku, se neodděluje). 4.3.4 4.3.5 a) vložený derivát (vložené deriváty) nemění podstatně peněžní toky, které by jinak byly smlouvou požadovány, nebo b) je při prvním posouzení podobného hybridního nástroje na první pohled patrné, že vyčlenění vloženého derivátu (vložených derivátů) není povoleno, jako například u opce předčasného splacení vložené do úvěrové smlouvy, která umožňuje držiteli předplatit úvěr přibližně naběhlou hodnotou. 4.3.6 4.3.7 4.4   REKLASIFIKACE'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 15, null, '4.4.1 4.4.2 4.4.3 a) položka, která dříve plnila funkci určeného a efektivního zajišťovacího nástroje při zajištění peněžních toků nebo zajištění čisté investice, se již jako taková nekvalifikuje; b) položka začne plnit funkci určeného a efektivního zajišťovacího nástroje při zajištění peněžních toků nebo zajištění čisté investice a c) změny oceňování v souladu s oddílem 6.7. KAPITOLA 5   Oceňování 5.1   PRVOTNÍ OCENĚNÍ 5.1.1 5.1.1A 5.1.2 5.1.3 5.2   NÁSLEDNÉ OCENĚNÍ FINANČNÍCH AKTIV 5.2.1 a) naběhlou hodnotou; b) reálnou hodnotou do ostatního úplného výsledku nebo c) reálnou hodnotou do hospodářského výsledku. 5.2.2 5.2.3 5.3   NÁSLEDNÉ OCENĚNÍ FINANČNÍCH ZÁVAZKŮ 5.3.1 5.3.2 5.4   OCEŇOVÁNÍ NABĚHLOU HODNOTOU Finanční aktiva Metoda efektivní úrokové míry 5.4.1 a) nakoupených nebo vzniklých úvěrově znehodnocených finančních aktiv. U těchto finančních aktiv musí účetní jednotka od prvotního uznání uplatnit efektivní úrokovou míru upravenou o úvěrové riziko na naběhlou hodnotu finančního aktiva; b) finančních aktiv, které nejsou nakoupenými nebo vzniklými úvěrově znehodnocenými finančními aktivy, avšak následně se staly úvěrově znehodnocenými finančními aktivy. U těchto finančních aktiv musí účetní jednotka v následujících vykazovaných obdobích uplatňovat efektivní úrokovou míru na naběhlou hodnotu finančního aktiva. 5.4.2 Modifikace smluvních peněžních toků 5.4.3 Odpis 5.4.4 Změny báze pro určení smluvních peněžních toků v důsledku reformy referenčních úrokových sazeb'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 16, null, '5.4.5 5.4.6 a) změnou smluvních podmínek určených při prvotním uznání finančního nástroje (například při změně smluvních podmínek tak, že je referenční úroková sazba nahrazena alternativní referenční sazbou); b) způsobem, který nebyl brán v úvahu – nebo zamýšlen – ve smluvních podmínkách při prvotním uznání finančního nástroje, beze změny smluvních podmínek (například se změní metoda výpočtu referenční úrokové sazby, aniž by se změnily smluvní podmínky), a/nebo c) kvůli aktivaci stávající smluvní podmínky (například při uplatnění již existujícího nouzového ustanovení). 5.4.7 a) změna je nezbytná jakožto přímý důsledek reformy referenčních úrokových sazeb a b) nová báze pro určení smluvních peněžních toků je ekonomicky rovnocenná s předchozí bází (tj. bází bezprostředně předcházející změně). 5.4.8 a) nahrazení stávající referenční úrokové sazby používané k určení smluvních peněžních toků finančních aktiv nebo finančních závazků alternativní referenční úrokovou sazbou – nebo provedení takové reformy referenční úrokové sazby, že se změní metoda použitá k jejímu výpočtu – s přidáním pevného rozpětí nezbytného pro kompenzaci rozdílu v bázi mezi stávající referenční úrokovou sazbou a alternativní referenční úrokovou sazbou; b) změny týkající se období fixace, dat fixace nebo počtu dní mezi daty kupónových plateb, aby bylo možné provést reformu referenčních úrokových sazeb, a c) přidání nouzového ustanovení ke smluvním podmínkám finančního aktiva nebo finančního závazku, které umožní provedení změn popsaných výše v písmeni a) a b). 5.4.9 5.5   ZNEHODNOCENÍ'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 17, null, 'Uznání očekávaných úvěrových ztrát Obecný přístup 5.5.1 5.5.2 5.5.3 5.5.4 5.5.5 5.5.6 5.5.7 5.5.8 Určení podstatného zvýšení úvěrového rizika 5.5.9 5.5.10 5.5.11 Modifikovaná finanční aktiva 5.5.12 a) rizika selhání k datu vykázání (na základě upravených smluvních podmínek) a b) rizika selhání při prvotním uznání (na základě původních, neupravených smluvních podmínek). Nakoupená nebo vzniklá úvěrově znehodnocená finanční aktiva 5.5.13 5.5.14 Zjednodušený přístup k obchodním pohledávkám, smluvním aktivům a pohledávkám z leasingu 5.5.15 a) obchodní pohledávky nebo smluvní aktiva, jež jsou výsledkem transakcí, které jsou v působnosti IFRS 15 a které: i) neobsahují podstatnou složku financování v souladu s IFRS 15 (nebo pokud účetní jednotka uplatní praktické zjednodušení v souladu s odstavcem 63 IFRS 15) nebo ii) obsahují podstatnou složku financování v souladu s IFRS 15, pokud si účetní jednotka jako své účetní pravidlo zvolí vyčíslení opravné položky ve výši očekávaných úvěrových ztrát za dobu trvání. Toto účetní pravidlo musí být použito pro všechny takové obchodní pohledávky nebo smluvní aktiva, avšak může být použito zvlášť pro obchodní pohledávky a pro smluvní aktiva; b) pohledávky z leasingu, jež jsou výsledkem transakcí, které jsou v působnosti IFRS 16, pokud si účetní jednotka jako své účetní pravidlo zvolí vyčíslení opravné položky ve výši očekávaných úvěrových ztrát za dobu trvání. Toto účetní pravidlo musí být použito na všechny pohledávky z leasingu, avšak může být použito zvlášť pro pohledávky z finančního a z operativního leasingu.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 18, null, '5.5.16 Vyčíslení očekávaných úvěrových ztrát 5.5.17 a) nezkreslenou a pravděpodobnostně váženou částku, která se určí vyhodnocením rozsahu možných výsledků; b) časovou hodnotu peněz a c) přiměřené a doložitelné informace, dostupné k datu vykázání bez nepřiměřených nákladů nebo úsilí, o minulých událostech, současných podmínkách a prognózách budoucích ekonomických podmínek. 5.5.18 5.5.19 5.5.20 5.6   REKLASIFIKACE FINANČNÍCH AKTIV 5.6.1 5.6.2 5.6.3 5.6.4 5.6.5 5.6.6 5.6.7 5.7   ZISKY A ZTRÁTY 5.7.1 a) toto finanční aktivum nebo finanční závazek je součástí zajišťovacího vztahu (viz odstavce 6.5.8–6.5.14 a případně odstavce 89–94 standardu IAS 39 pro zajištění reálné hodnoty portfolia proti úrokovému riziku); b) se jedná o investici do kapitálového nástroje a účetní jednotka se v souladu s odstavcem 5.7.5 rozhodla, že zisky a ztráty bude vykazovat v ostatním úplném výsledku; c) se jedná o finanční závazek označený za nástroj oceňovaný reálnou hodnotou do hospodářského výsledku a účetní jednotka je v souladu s odstavcem 5.7.7 povinna vykazovat dopady změn úvěrového rizika tohoto závazku v ostatním úplném výsledku nebo d) se jedná o finanční aktivum oceňované reálnou hodnotou do ostatního úplného výsledku v souladu s odstavcem 4.1.2A a účetní jednotka je povinna uznat určité změny reálné hodnoty do ostatního úplného výsledku v souladu s odstavcem 5.7.10. 5.7.1A a) vznikne právo účetní jednotky na přijetí platby dividendy; b) je pravděpodobné, že ekonomický prospěch spojený s dividendou účetní jednotce poplyne, a c) výše dividendy může být spolehlivě stanovena.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 19, null, '5.7.2 5.7.3 5.7.4 Investice do kapitálových nástrojů 5.7.5 5.7.6 Závazky označené jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku 5.7.7 a) částka změny reálné hodnoty finančního závazku, která je důsledkem změn úvěrového rizika souvisejícího s tímto závazkem, se vykáže do ostatního úplného výsledku (viz odstavce B5.7.13–B5.7.20) a b) zbývající částka změny reálné hodnoty závazku se vykáže do hospodářského výsledku, ale pouze pokud by způsob účtování dopadů změn úvěrového rizika souvisejícího s daným závazkem popsaný v písmenu a) nevedl ke vzniku nebo zvětšení účetní neshody v hospodářském výsledku (v takovém případě se použije odstavec 5.7.8). Vodítko při rozhodování, zda by došlo ke vzniku nebo zvětšení účetní neshody, je dáno v odstavcích B5.7.5–B5.7.7 a B5.7.10–B5.7.12. 5.7.8 5.7.9 Aktiva oceňovaná reálnou hodnotou do ostatního úplného výsledku 5.7.10 5.7.11 KAPITOLA 6   Zajišťovací účetnictví 6.1   CÍL A ROZSAH PŮSOBNOSTI ZAJIŠŤOVACÍHO ÚČETNICTVÍ 6.1.1 6.1.2 6.1.3 6.2   ZAJIŠŤOVACÍ NÁSTROJE Co může být zajišťovacím nástrojem 6.2.1 6.2.2 6.2.3 Použití zajišťovacího nástroje 6.2.4 a) oddělení vnitřní hodnoty a časové hodnoty opce, přičemž funkci zajišťovacího nástroje bude plnit pouze změna vnitřní hodnoty opce, a nikoli změna její časové hodnoty (viz odstavce 6.5.15 a B6.5.29–B6.5.33);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 20, null, 'b) oddělení forwardové části a spotové části forwardové smlouvy, přičemž funkci zajišťovacího nástroje bude plnit pouze změna hodnoty spotové části forwardové smlouvy, a nikoli forwardová část; podobně lze oddělit měnové bazické rozpětí (basis spread) a vyloučit je z použití finančního nástroje jako zajišťovacího nástroje (viz odstavce 6.5.16 a B6.5.34–B6.5.39) a c) pro potřeby zajišťovacího vztahu je možné jako zajišťovací nástroj použít proporční část celého zajišťovacího nástroje, např. 50 % jeho jmenovité hodnoty. Jako zajišťovací nástroj však nelze použít část změny jeho reálné hodnoty, která je spojena pouze s částí období do doby, než je zajišťovací nástroj vypořádán. 6.2.5 a) deriváty nebo jejich proporční část a b) ne-derivátové smlouvy nebo jejich proporční část. 6.2.6 6.3   ZAJIŠTĚNÉ POLOŽKY Co může být zajištěnou položkou 6.3.1 a) jednotlivá položka nebo b) skupina položek (splňující požadavky odstavců 6.6.1–6.6.6 a B6.6.1–B6.6.16). Zajištěnou položkou může být také část takové položky nebo skupiny položek (viz odstavce 6.3.7 a B6.3.7–B6.3.25). 6.3.2 6.3.3 6.3.4 6.3.5 6.3.6 Použití zajištěných položek'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 21, null, '6.3.7 a) pouze změny peněžních toků nebo změny reálné hodnoty položky, která je důsledkem specifického rizika nebo specifických rizik (riziková složka) pod podmínkou, že na základě posouzení v kontextu struktury daného konkrétního trhu lze rizikovou část samostatně identifikovat a spolehlivě ocenit (viz odstavce B6.3.8–B6.3.15). V rámci rizikové složky je možné určit jako zajištěné položky pouze peněžní toky nebo reálné hodnoty nad nebo pod určitou cenu nebo jinou proměnnou („jednostranné riziko“); b) jeden nebo více vybraných smluvních peněžních toků; c) složky jmenovité hodnoty, tj. určenou část hodnoty položky (viz odstavce B6.3.16–B6.3.20). 6.4   KRITÉRIA PRO POUŽITÍ ZAJIŠŤOVACÍHO ÚČETNICTVÍ 6.4.1 a) zajišťovací vztah sestává pouze ze způsobilých zajišťovacích nástrojů a způsobilých zajištěných položek; b) na počátku zajišťovacího vztahu existuje formální určení a zdokumentování zajišťovacího vztahu, cílů účetní jednotky v oblasti řízení rizik a strategie při realizaci zajištění. Tato dokumentace musí zahrnovat identifikaci zajišťovacího nástroje, zajištěné položky, povahu rizika, proti němuž se zajišťuje, a způsob jakým bude účetní jednotka posuzovat, zda zajišťovací vztah splňuje požadavky na efektivnost zajištění (včetně analýzy zdrojů neefektivnosti zajištění a toho, jak účetní jednotka určuje zajišťovací poměr); c) zajišťovací vztah splňuje všechny následující požadavky na efektivnost zajištění: i) mezi zajištěnou položkou a zajišťovacím nástrojem existuje ekonomický vztah (viz odstavce B6.4.4–B6.4.6);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 22, null, 'ii) dopad úvěrového rizika není rozhodujícím faktorem pro změny hodnoty vyplývající z tohoto ekonomického vztahu (viz odstavce B6.4.7–B6.4.8) a iii) zajišťovací poměr daného zajišťovacího vztahu je stejný jako poměr množství zajištěné položky, který účetní jednotka skutečně zajišťuje, a množství zajišťovacího nástroje, který účetní jednotka skutečně používá k zajištění tohoto množství zajištěné položky. Toto určení však nesmí odrážet nerovnováhu mezi váhou přisouzenou zajištěné položce a váhou přisouzenou zajišťovacímu nástroji, která by způsobovala neefektivnost zajištění (bez ohledu na to, zda byla uznána, či nikoli), jež by mohla vést k účetnímu výsledku, který by nebyl v souladu s účelem zajišťovacího účetnictví (viz odstavce B6.4.9–B6.4.11). 6.5   ÚČTOVÁNÍ O ZPŮSOBILÝCH ZAJIŠŤOVACÍCH VZTAZÍCH 6.5.1 6.5.2 a) zajištění reálné hodnoty: zajištění expozice vůči riziku změn reálné hodnoty uznaného aktiva nebo závazku nebo neuznaného závazného příslibu nebo složky jakékoli takové položky, které jsou důsledkem konkrétního rizika a které mohou ovlivnit hospodářský výsledek; b) zajištění peněžních toků: zajištění expozice vůči riziku variability peněžních toků, které plynou z konkrétního rizika spojeného se všemi uznanými aktivy nebo závazky nebo s nějakou jejich složkou (jako jsou veškeré nebo některé budoucí platby úroků z dluhu s proměnlivou úrokovou sazbou) nebo s vysoce pravděpodobnou očekávanou transakcí a mohou ovlivnit hospodářský výsledek; c) zajištění čisté investice do zahraniční jednotky, jak je definována ve standardu IAS 21.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 23, null, '6.5.3 6.5.4 6.5.5 6.5.6 a) v důsledku právních předpisů nebo zavedení nových právních předpisů se strany, které sjednaly zajišťovací nástroj, dohodnou, že jejich původní protistranu nahradí jedna nebo více protistran provádějících clearing, které se stanou novými protistranami všech stran. Pro tento účel je protistranou provádějící clearing centrální protistrana (někdy nazývaná „clearingová organizace“ nebo „clearingová agentura“) nebo osoba či osoby, například člen clearingové organizace nebo klient člena clearingové organizace, kteří vystupují jako protistrana, aby provedli clearing jako centrální protistrana. Pokud však strany zajišťovacího nástroje nahradí své původní protistrany různými protistranami, je požadavek uvedený v tomto písmenu splněn pouze v případě, že všechny tyto strany provádějí clearing prostřednictvím téže centrální protistrany; b) případné další změny zajišťovacího nástroje se omezují na změny nezbytné k realizaci takového nahrazení protistrany. Tyto změny musí být v souladu s podmínkami, jež by se daly předpokládat, pokud by clearing zajišťovacího nástroje uskutečnila původní protistrana provádějící clearing. Tyto změny zahrnují změny požadavků na kolaterál, práv na vyrovnání salda pohledávek a závazků a vybíraných poplatků; Ukončení účtování o zajištění může ovlivnit buď zajišťovací účetnictví jako celek, nebo pouze jeho část (v takovém případě pokračuje zajišťovací účetnictví u ostatních zajišťovacích vztahů).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 24, null, '6.5.7 a) odstavec 6.5.10, když přestane účtovat o zajištění reálné hodnoty, ve kterém je zajištěná položka (nebo její složka) finančním nástrojem oceňovaným naběhlou hodnotou, a b) odstavec 6.5.12, když přestane účtovat o zajištění peněžních toků. Zajištění reálné hodnoty 6.5.8 a) zisk nebo ztráta ze zajišťovacího nástroje se uznají do hospodářského výsledku (nebo do ostatního úplného výsledku, pokud tento zajišťovací nástroj zajišťuje kapitálový nástroj, u nějž se účetní jednotka v souladu s odstavcem 5.7.5 rozhodla vykazovat změny reálné hodnoty do ostatního úplného výsledku); b) účetní hodnota zajištěné položky (je-li to použitelné) se upraví o zisk nebo ztrátu ze zajištění zajištěné položky a uzná se do hospodářského výsledku. Pokud je zajištěná položka finančním aktivem (nebo jeho složkou), které se v souladu s odstavcem 4.1.2A oceňuje reálnou hodnotou do ostatního úplného výsledku, musí se zisk nebo ztráta ze zajištění této zajištěné položky uznat do hospodářského výsledku. Pokud je však zajištěná položka kapitálovým nástrojem, u nějž se účetní jednotka v souladu s odstavcem 5.7.5 rozhodla vykazovat změny reálné hodnoty v ostatním úplném výsledku, musí tyto částky zůstat v ostatním úplném výsledku. Pokud je zajištěná položka neuznaným závazným příslibem (nebo jeho složkou), kumulovaná změna reálné hodnoty této zajištěné položky od okamžiku, kdy byla takto nastavena, se uzná jako aktivum nebo závazek, přičemž příslušný zisk nebo ztráta se uzná do hospodářského výsledku. 6.5.9 6.5.10 Zajištění peněžních toků'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 25, null, '6.5.11 a) samostatná složka vlastního kapitálu, která souvisí se zajištěnou položkou (oceňovací rozdíl ze zajištění peněžních toků), se upraví na následující hodnotu (v absolutních částkách): i) kumulovaný zisk nebo ztráta plynoucí ze zajišťovacího nástroje od počátku zajišťovacího vztahu a ii) kumulovaná změna reálné hodnoty (současná hodnota) zajištěné položky (tj. současná hodnota kumulované změny předpokládaných budoucích peněžních toků souvisejících se zajištěním) od počátku zajištění, je-li nižší; b) část zisku nebo ztráty ze zajišťovacího nástroje, který je posouzen jako efektivní zajištění (tj. část, která je kompenzovaná změnou oceňovacího rozdílu ze zajištění peněžních toků vypočtenou v souladu s písmenem a)), se uzná do ostatního úplného výsledku; c) jakýkoli zbývající zisk nebo ztráta plynoucí ze zajišťovacího nástroje (nebo jakýkoli zisk nebo ztráta, které jsou zapotřebí k vyvážení změny oceňovacího rozdílu ze zajištění peněžních toků vypočtené v souladu s písmenem a)) je neefektivnost zajištění, která se musí uznat do hospodářského výsledku; d) částka kumulovaná v oceňovacím rozdílu ze zajištění peněžních toků v souladu s písmenem a) se musí účtovat následujícím způsobem:'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 26, null, 'i) pokud zajišťovaná očekávaná transakce následně vyústí v uznání nefinančního aktiva nebo nefinančního závazku nebo pokud se zajištěná očekávaná transakce pro zajištění nefinančního aktiva nebo nefinančního závazku stane závazným příslibem, na který se použije zajištění reálné hodnoty, musí účetní jednotka vyřadit tuto částku z oceňovacího rozdílu ze zajištění peněžních toků a zahrnout ji přímo do počátečních pořizovacích nákladů nebo jiné účetní hodnoty aktiva nebo závazku. V tomto případě se nejedná o reklasifikační úpravu (viz standard IAS 1), a tudíž nemá vliv na ostatní úplný výsledek; ii) v případech zajištění peněžních toků, které nejsou popsány v bodě i), se tato částka musí reklasifikovat z oceňovacího rozdílu ze zajištění peněžních toků do hospodářského výsledku jako reklasifikační úprava (viz standard IAS 1) ve stejném období nebo obdobích, během nichž zajištěné předpokládané budoucí peněžní toky ovlivní hospodářský výsledek (například v obdobích, kdy se účtuje o úrokových výnosech nebo o úrokových nákladech nebo když dojde k očekávanému prodeji); iii) pokud je však tato částka ztrátou a účetní jednotka očekává, že celá tato ztráta nebo její část v jednom nebo více budoucích období nebude vymožitelná, musí částku, u níž se neočekává vymožení, okamžitě reklasifikovat do hospodářského výsledku jako reklasifikační úpravu (viz standard IAS 1).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 27, null, '6.5.12 a) pokud se očekává, že se zajištěné budoucí peněžní toky uskuteční, musí tato částka být ponechána v oceňovacím rozdílu ze zajištění peněžních toků, dokud daný budoucí peněžní tok nenastane nebo dokud se nepoužije ustanovení odst. 6.5.11 písm. d) bodu iii). Jakmile daný budoucí peněžní tok nastane, použije se odst. 6.5.11 písm. d); b) pokud se již neočekává, že by zajištěné budoucí peněžní toky nastaly, musí se tato částka okamžitě přeřadit z oceňovacího rozdílu ze zajištění peněžních toků do hospodářského výsledku jako reklasifikační úprava (viz standard IAS 1). Zajištěný budoucí peněžní tok, jehož existence již není vysoce pravděpodobná, není nutně třeba považovat za již neočekávaný. Zajištění čisté investice do zahraniční jednotky 6.5.13 a) část zisku nebo ztráty ze zajišťovacího nástroje, který je hodnocen jako efektivní zajištění, se uzná v ostatním úplném výsledku (viz odstavec 6.5.11) a b) neefektivní část se uzná do hospodářského výsledku. 6.5.14 Účtování o časové hodnotě opcí 6.5.15 a) účetní jednotka musí rozlišovat mezi časovou hodnotou opcí podle typu zajištěné položky, kterou tato opce zajišťuje (viz odstavec B6.5.29): i) zajištěná položka spojená s transakcí, nebo ii) zajištěná položka spojená s časovým obdobím;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 28, null, 'b) změna reálné hodnoty časové hodnoty opce, která zajišťuje zajištěnou položku spojenou s transakcí, musí být uznána do ostatního úplného výsledku v rozsahu, v němž je spojena se zajištěnou položkou, a musí být kumulována v samostatné složce vlastního kapitálu. Kumulovaná změna reálné hodnoty vyplývající z časové hodnoty opce, která byla kumulována v samostatné složce vlastního kapitálu („částka“), se musí účtovat následujícím způsobem: i) pokud zajišťovaná očekávaná transakce následně vyústí v uznání nefinančního aktiva nebo nefinančního závazku nebo pokud se zajištěná očekávaná transakce stane závazným příslibem nefinančního aktiva nebo nefinančního závazku, na který se použije zajištění reálné hodnoty, musí účetní jednotka vyřadit tuto částku ze samostatné složky vlastního kapitálu a zahrnout ji přímo do počátečních pořizovacích nákladů nebo jiné účetní hodnoty aktiva nebo závazku. Nejedná se o reklasifikační úpravu (viz standard IAS 1), a tudíž nemá vliv na ostatní úplný výsledek; ii) u těch zajišťovacích vztahů, které nejsou popsány v bodě i), se tato částka musí reklasifikovat ze samostatné složky vlastního kapitálu do hospodářského výsledku jako reklasifikační úprava (viz IAS 1) ve stejném období nebo obdobích, během kterých mají zajištěné předpokládané budoucí peněžní toky vliv na hospodářský výsledek (například když dojde k očekávanému prodeji);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 29, null, 'iii) pokud však účetní jednotka očekává, že celá tato částka nebo její část v jednom nebo více budoucích obdobích nebude vymožitelná, musí částku, u níž neočekává vymožení, okamžitě převést do hospodářského výsledku jako reklasifikační úpravu (viz standard IAS 1); c) změna reálné hodnoty časové hodnoty opce, která zajišťuje zajištěnou položku spojenou s časovým obdobím, musí být uznána do ostatního úplného výsledku v tom rozsahu, v jakém je spojena se zajištěnou položkou, a musí být kumulována v samostatné složce vlastního kapitálu. Časová hodnota k datu zaúčtování opce jako zajišťovacího nástroje, v tom rozsahu, v jakém je spojena se zajištěnou položkou, se musí amortizovat na systematické a racionální bázi za období, během kterého úprava zajištění vnitřní hodnoty opce mohla ovlivňovat hospodářský výsledek (nebo ostatní úplný výsledek, pokud zajištěná položka je kapitálovým nástrojem, u kterého se účetní jednotka v souladu s odstavcem 5.7.5 rozhodla vykazovat změny reálné hodnoty do ostatního úplného výsledku). V každém účetním období tedy musí být amortizovaná částka reklasifikována ze samostatné složky vlastního kapitálu do hospodářského výsledku jako reklasifikační úprava (viz standard IAS 1). Pokud je však ukončeno účtování o zajišťovacím vztahu, jež zahrnuje změnu vnitřní hodnoty opce jako zajišťovacího nástroje, musí účetní jednotka částku čisté výše (tj. včetně kumulované amortizace), která se nakumulovala v samostatné složce vlastního kapitálu, okamžitě převést do hospodářského výsledku jako reklasifikační úpravu (viz standard IAS 1).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 30, null, 'Účtování o forwardové části forwardových smluv a o měnovém bazickém rozpětí (basis spread) finančních nástrojů 6.5.16 6.6   ZAJIŠTĚNÍ SKUPINY POLOŽEK Způsobilost skupiny položek plnit funkci zajištěné položky 6.6.1 a) se skládá z položek (včetně složek položek), které jsou každá jednotlivě způsobilé plnit funkci zajištěné položky; b) položky ve skupině jsou pro účely řízení rizik řízeny společně na skupinovém základě a c) v případě zajištění peněžních toků skupiny položek, kde se neočekává, že variabilita peněžních toků bude přibližně odpovídat celkové variabilitě peněžních toků ve skupině, takže vzniknou pozice s kompenzujícími se riziky: i) se jedná o zajištění měnového rizika a ii) určení této čisté pozice obsahuje specifikaci účetního období, v němž se očekává, že očekávané transakce ovlivní hospodářský výsledek, jakož i povahu a objem těchto očekávaných transakcí (viz odstavce B6.6.7–B6.6.8). Určení složky se jmenovitou hodnotou k použití 6.6.2 6.6.3 a) je možné ji samostatně identifikovat a spolehlivě vyčíslit; b) cílem řízení rizik je zajistit takovouto vrstvu; c) položky v celé skupině, v níž byla daná vrstva identifikována, jsou vystaveny stejnému zajišťovanému riziku (takže ocenění zajištěné vrstvy není podstatně ovlivněno tím, které konkrétní položky z celé skupiny tvoří součást zajištěné vrstvy);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 31, null, 'd) pro zajištění stávajících položek (například neuznaného závazného příslibu nebo uznaného aktiva) je účetní jednotka schopna identifikovat a průběžně sledovat celou skupinu položek, v níž je daná zajištěná vrstva identifikována (takže účetní jednotka je schopna splnit požadavky na účtování způsobilých zajišťovacích vztahů); e) všechny položky skupiny, které obsahují opci na předčasné splacení, splňují požadavky týkající se složek jmenovité hodnoty (viz odstavec B6.3.20). Vykazování 6.6.4 6.6.5 Nulové čisté pozice 6.6.6 a) zajištění je součástí strategie průběžného zajišťování čistého rizika, přičemž tato účetní jednotka s postupem času běžně zajišťuje nové pozice stejného typu (například, když se transakce přesune do časového horizontu, na který účetní jednotka zajišťuje); b) zajištěná čistá pozice mění svou velikost po dobu trvání strategie průběžného zajišťování čistého rizika a účetní jednotka používá vhodné zajišťovací nástroje k zajištění čistého rizika (tj. když čistá pozice není nulová); c) k zajištění těchto čistých pozic, kde čistá pozice není nulová a je zajištěna způsobilým zajišťovacím nástrojem, se obvykle používá zajišťovací účetnictví; d) neúčtování zajištění nulových čistých pozic by vedlo k nesourodým účetním výsledkům, protože účetnictví by neuznalo vzájemně se kompenzující rizikové pozice, které by jinak při zajištění čisté pozice byly uznány. 6.7   MOŽNOST URČIT ÚVĚROVOU EXPOZICI JAKO OCEŇOVANOU REÁLNOU HODNOTU DO HOSPODÁŘSKÉHO VÝSLEDKU Způsobilost úvěrových expozic k oceňování reálnou hodnotou do hospodářského výsledku'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 32, null, '6.7.1 a) se název expozice vůči úvěrovým rizikům (např. dlužník nebo držitel úvěrového příslibu) shoduje s referenčním subjektem úvěrového derivátu („shoda názvu“) a b) nadřízenost finančního nástroje odpovídá nadřízenosti nástrojů, které lze poskytnout v souladu s podmínkami úvěrového derivátu. Účetní jednotka může provést toto určení bez ohledu na to, zda finanční nástroj, který je použit k řízení úvěrových rizik, je v působnosti tohoto standardu (například, účetní jednotka může takto určit úvěrové přísliby, které jsou mimo působnost tohoto standardu). Účetní jednotka může tento finanční nástroj určit při prvotním uznání nebo později, nebo když není uznán. Toto určení musí účetní jednotka neprodleně zdokumentovat. Účtování úvěrových expozic určených jako oceňované reálnou hodnotou do hospodářského výsledku 6.7.2 6.7.3 a) kritéria způsobilosti uvedená v odstavci 6.7.1 již nejsou splněna, například: i) uplyne platnost úvěrového derivátu nebo souvisejícího finančního nástroje, který vedl ke vzniku úvěrového rizika, nebo je tento úvěrový derivát nebo finanční nástroj prodán, ukončen nebo uplatněn, nebo ii) úvěrové riziko finančního nástroje již nadále není řízeno prostřednictvím úvěrových derivátů. Toto by mohlo nastat například z důvodu zlepšení úvěrové kvality dlužníka nebo držitele úvěrového příslibu nebo v důsledku změn kapitálových požadavků uložených účetní jednotce, a'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 33, null, 'b) finanční nástroj, který vedl ke vzniku úvěrového rizika, jinak nemusí být oceňován reálnou hodnotou do hospodářského výsledku (tj. obchodní model účetní jednotky se mezitím nezměnil tak, aby byla nezbytná reklasifikace v souladu s odstavcem 4.4.1). 6.7.4 6.8   DOČASNÉ VÝJIMKY Z UPLATŇOVÁNÍ ZVLÁŠTNÍCH POŽADAVKŮ NA ZAJIŠŤOVACÍ ÚČETNICTVÍ 6.8.1 a) referenční úrokovou sazbu (specifikovanou smluvně nebo mimosmluvně) určenou jako zajištěné riziko a/nebo b) načasování nebo částku peněžních toků založených na referenční úrokové sazbě u zajištěné položky nebo zajišťovacího nástroje. 6.8.2 6.8.3 Požadavek na vysokou pravděpodobnost u zajištění peněžních toků 6.8.4 Reklasifikace částky kumulované v oceňovacím rozdílu ze zajištění peněžních toků 6.8.5 Posouzení ekonomického vztahu mezi zajištěnou položkou a zajišťovacím nástrojem 6.8.6 Určení složky určité položky jako zajištěné položky 6.8.7 6.8.8 Konec použití 6.8.9 a) když nejistota vyplývající z reformy referenčních úrokových sazeb, pokud jde o načasování a výši peněžních toků založených na referenční úrokové sazbě u zajištěné položky, přestane existovat, nebo b) když je zajišťovací vztah, jehož je zajištěná položka součástí, ukončen, nastane-li tato situace dříve. 6.8.10 a) když nejistota vyplývající z reformy referenčních úrokových sazeb, pokud jde o načasování a výši budoucích peněžních toků založených na referenční úrokové sazbě u zajištěné položky, přestane existovat, nebo'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 34, null, 'b) když celkový kumulovaný zůstatek z oceňovacích rozdílů ze zajištění peněžních toků ve vztahu k tomuto ukončenému zajišťovacímu vztahu, byl reklasifikován do hospodářského výsledku, nastane-li tato situace dříve. 6.8.11 a) na zajištěnou položku, když nejistota vyplývající z reformy referenčních úrokových sazeb, pokud jde o zajištěné riziko nebo načasování a výši peněžních toků založených na referenční úrokové sazbě u zajištěné položky, přestane existovat, nebo b) na zajišťovací nástroj, když nejistota vyplývající z reformy referenčních úrokových sazeb, pokud jde o načasování a výši peněžních toků založených na referenční úrokové sazbě u zajišťovacího nástroje, přestane existovat, nastane-li tato situace dříve. Pokud je zajišťovací vztah, jehož součástí jsou zajištěná položka a zajišťovací nástroj, ukončen dříve než k datu uvedenému v odst. 6.8.11 písm. a) nebo k datu uvedenému v odst. 6.8.11 písm. b), musí účetní jednotka na tento zajišťovací vztah k datu jeho ukončení přestat prospektivně uplatňovat odstavec 6.8.6. 6.8.12 6.8.13 a) když jsou změny požadované reformou referenčních úrokových sazeb provedeny u mimosmluvně specifikované složky rizika za použití odstavce 6.9.1 nebo b) když je ukončen zajišťovací vztah, ve kterém je mimosmluvně specifikovaná složka rizika určena, nastane-li tato situace dříve. 6.9   DODATEČNÉ DOČASNÉ VÝJIMKY VYPLÝVAJÍCÍ Z REFORMY REFERENČNÍCH ÚROKOVÝCH SAZEB 6.9.1 a) určení alternativní referenční sazby (specifikované smluvně nebo mimosmluvně) jako zajištěného rizika;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 35, null, 'b) změny popisu zajištěné položky, včetně popisu určené části peněžních toků nebo reálné hodnoty, která se zajišťuje, nebo c) změny popisu zajišťovacího nástroje. 6.9.2 a) účetní jednotka provede změnu požadovanou reformou referenčních úrokových sazeb s využitím jiného přístupu než změny báze pro určení smluvních peněžních toků zajišťovacího nástroje (jak je popsáno v odstavci 5.4.6); b) původní zajišťovací nástroj není vyňat a c) zvolený přístup je ekonomicky rovnocenný se změnou báze pro určení smluvních peněžních toků původního zajišťovacího nástroje (jak je popsáno v odstavcích 5.4.7 a 5.4.8). 6.9.3 6.9.4 6.9.5 6.9.6 Účtování o způsobilých zajišťovacích vztazích Zajištění peněžních toků 6.9.7 6.9.8 Skupiny položek 6.9.9 6.9.10 Určení složek rizika 6.9.11 6.9.12 6.9.13 KAPITOLA 7   Datum účinnosti a přechodná ustanovení 7.1   DATUM ÚČINNOSTI 7.1.1 7.1.2 7.1.3 7.1.4 7.1.5 7.1.6 7.1.7 7.1.8 7.1.9 7.1.10 7.2   PŘECHODNÁ USTANOVENÍ 7.2.1 7.2.2 Přechodná ustanovení pro klasifikaci a oceňování (kapitoly 4 a 5) 7.2.3 7.2.4 7.2.5 7.2.6 7.2.7 7.2.8 a) finanční aktivum jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku v souladu s odstavcem 4.1.5 nebo b) investici do kapitálového nástroje jako nástroj oceňovaný reálnou hodnotou do ostatního úplného výsledku v souladu s odstavcem 5.7.5. Takové určení musí být provedeno na základě skutečností a okolností existujících k datu prvotní aplikace. Tato klasifikace musí být provedena zpětně.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 36, null, '7.2.9 a) musí zrušit své předchozí určení finančního aktiva jako nástroje oceňovaného reálnou hodnotou hospodářského výsledku, pokud toto finanční aktivum nesplňuje podmínku stanovenou v odstavci 4.1.5; b) může zrušit své předchozí určení finančního aktiva jako nástroje oceňovaného reálnou hodnotou do hospodářského výsledku, pokud toto finanční aktivum splňuje podmínku stanovenou v odstavci 4.1.5. Takové zrušení musí být provedeno na základě skutečností a okolností existujících k datu prvotní aplikace. Tato klasifikace musí být provedena zpětně. 7.2.10 a) v souladu s odst. 4.2.2 písm. a) může určit finanční závazek jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku; b) musí zrušit své předchozí určení finančního závazku jako nástroje oceňovaného reálnou hodnotou do hospodářského výsledku, pokud byl takto určen při prvotním uznání v souladu s podmínkou stanovenou nyní v odst. 4.2.2 písm. a) a pokud k datu prvotní aplikace takové určení tuto podmínku nesplňuje; c) může zrušit své předchozí určení finančního závazku jako nástroje oceňovaného reálnou hodnotou do hospodářského výsledku, pokud byl takto určen při prvotním uznání v souladu s podmínkou stanovenou nyní v odst. 4.2.2 písm. a) a pokud k datu prvotní aplikace takové určení tuto podmínku splňuje. Takové určení a zrušení musí být provedeno na základě skutečností a okolností existujících k datu prvotní aplikace. Tato klasifikace musí být provedena zpětně.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 37, null, '7.2.11 a) reálnou hodnotu finančního aktiva nebo finančního závazku na konci každého vykazovaného srovnávacího období, jako hrubou účetní hodnotu tohoto finančního aktiva nebo jako naběhlou hodnotu tohoto finančního závazku, pokud účetní jednotka upravuje údaje za minulá období, a b) reálnou hodnotu finančního aktiva nebo finančního závazku k datu prvotní aplikace, jako novou hrubou účetní hodnotu tohoto finančního aktiva nebo jako novou naběhlou hodnotu tohoto finančního závazku k datu prvotní aplikace tohoto standardu. 7.2.12 7.2.13 7.2.14 7.12.14A 7.2.15 7.2.16 Znehodnocení (oddíl 5.5) 7.2.17 7.2.18 7.2.19 a) požadavky uvedené v odstavcích 5.5.10 a B5.5.22–B5.5.24 a b) vyvratitelný předpoklad uvedený v odstavci 5.5.11 o smluvních platbách, které jsou více než 30 dnů po splatnosti, pokud účetní jednotka uplatní požadavky na znehodnocení tak, že zjistí podstatná zvýšení úvěrového rizika od prvotního uznání těchto finančních nástrojů na základě informací o dnech po splatnosti. 7.2.20 Přechodná ustanovení pro zajišťovací účetnictví (kapitola 6) 7.2.21 7.2.22 7.2.23 7.2.24 7.2.25 a) může začít uplatňovat tyto požadavky od stejného okamžiku, kdy přestane uplatňovat požadavky zajišťovacího účetnictví podle standardu IAS 39, a b) případně musí považovat zajišťovací poměr v souladu se standardem IAS 39 za výchozí bod pro rebalancování zajišťovacího poměru u pokračujícího zajišťovacího vztahu. Jakýkoli zisk nebo ztráta plynoucí z takového rebalancování se uzná do hospodářského výsledku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 38, null, '7.2.26 a) musí použít účtování o časové hodnotě opcí v souladu s odstavcem 6.5.15 zpětně, pokud v souladu se standardem IAS 39 byla za zajišťovací nástroj v zajišťovacím vztahu označena pouze změna vnitřní hodnoty opce. Toto zpětné použití se vztahuje pouze na ty zajišťovací vztahy, které existovaly na začátku nejzazšího srovnávacího období nebo které byly jako zajišťovací vztahy nastaveny později; b) může použít účtování o forwardovém prvku forwardových smluv v souladu s odstavcem 6.5.16 zpětně, pokud v souladu se standardem IAS 39 byla jako zajišťovací nástroj v zajišťovacím vztahu určena pouze změna spotového prvku forwardové smlouvy. Toto zpětné použití se vztahuje pouze na ty zajišťovací vztahy, které existovaly na začátku nejzazšího srovnávacího období nebo které byly jako zajišťovací vztahy nastaveny později; Pokud se navíc účetní jednotka rozhodne používat toto účtování zpětně, musí být použito na všechny zajišťovací vztahy, které pro tuto volbu jsou způsobilé (tj. při přechodu nelze tuto volbu použít pouze pro některé zajišťovací vztahy). Účtování o měnovém bazickém rozpětí (basis spread) (viz odstavec 6.5.16) může být použito zpětně pro ty zajišťovací vztahy, které existovaly na začátku nejzazšího srovnávacího období nebo které byly jako zajišťovací vztahy nastaveny později; c) musí použít zpětně požadavek odstavce 6.5.6, že nedošlo k uplynutí platnosti nebo ukončení zajišťovacího nástroje, pokud:'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 39, null, 'i) v důsledku právních předpisů nebo zavedení právních předpisů se strany zajišťovacího nástroje dohodly, že jejich původní protistranu nahradí jedna nebo více protistran provádějících clearing, které se stanou novými protistranami všech stran, a ii) případné další změny zajišťovacího nástroje se omezují na změny nezbytné k realizaci takového nahrazení protistrany; d) retroaktivně použije požadavky oddílu 6.8. Toto retroaktivní použití se vztahuje pouze na zajišťovací vztahy, které existovaly na začátku vykazovaného období, v němž účetní jednotka prvotně použije tyto požadavky, nebo byly určeny poté, a na zůstatek z oceňovacích rozdílů ze zajištění peněžních toků, která existovala na začátku vykazovaného období, v němž účetní jednotka tyto požadavky prvotně použije. Účetní jednotky, které již dříve používaly standard IFRS 9 (2009), IFRS 9 (2010) nebo IFRS 9 (2013) 7.2.27 7.2.28 a) musí zrušit své předchozí určení finančního aktiva jako nástroje oceňovaného reálnou hodnotou do hospodářského výsledku, pokud toto určení bylo dříve učiněno v souladu s podmínkou stanovenou v odstavci 4.1.5, avšak v důsledku použití tohoto standardu tato podmínka již není naplněna; b) může určit finanční aktivum jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku, pokud by toto určení dříve nenaplňovalo podmínku stanovenou v odstavci 4.1.5, avšak v důsledku použití tohoto standardu je nyní tato podmínka naplněna;')
